import{_ as a,o as r,c as t,a5 as l}from"./chunks/framework.Cooo9kuv.js";const p=JSON.parse('{"title":"WordPress 全能广告管理插件 — WZ Ad Manager","description":"","frontmatter":{"标题":"WordPress 全能广告管理插件 — WZ Ad Manager","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["WordPress","代码广告","信息流广告","图片广告","广告管理","广告轮播","弹窗广告","插屏广告","网站变现"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"20 余种广告投放位置","slug":"_20-余种广告投放位置","link":"#_20-余种广告投放位置","children":[]},{"level":3,"title":"两种广告类型","slug":"两种广告类型","link":"#两种广告类型","children":[]},{"level":3,"title":"多广告轮播策略","slug":"多广告轮播策略","link":"#多广告轮播策略","children":[]},{"level":3,"title":"广告定时投放","slug":"广告定时投放","link":"#广告定时投放","children":[]},{"level":3,"title":"分类定向投放","slug":"分类定向投放","link":"#分类定向投放","children":[]},{"level":3,"title":"每日数据统计","slug":"每日数据统计","link":"#每日数据统计","children":[]},{"level":3,"title":"搜索引擎蜘蛛过滤","slug":"搜索引擎蜘蛛过滤","link":"#搜索引擎蜘蛛过滤","children":[]},{"level":3,"title":"移动端独立控制","slug":"移动端独立控制","link":"#移动端独立控制","children":[]},{"level":3,"title":"特殊广告交互","slug":"特殊广告交互","link":"#特殊广告交互","children":[]},{"level":3,"title":"评论区广告精准插入","slug":"评论区广告精准插入","link":"#评论区广告精准插入","children":[]},{"level":3,"title":"列表信息流广告","slug":"列表信息流广告","link":"#列表信息流广告","children":[]},{"level":3,"title":"内置图库管理","slug":"内置图库管理","link":"#内置图库管理","children":[]},{"level":3,"title":"列表内快速编辑","slug":"列表内快速编辑","link":"#列表内快速编辑","children":[]},{"level":3,"title":"中英双语界面","slug":"中英双语界面","link":"#中英双语界面","children":[]},{"level":3,"title":"广告标识与关闭","slug":"广告标识与关闭","link":"#广告标识与关闭","children":[]},{"level":3,"title":"安全代码过滤","slug":"安全代码过滤","link":"#安全代码过滤","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：创建广告","slug":"第二步-创建广告","link":"#第二步-创建广告","children":[]},{"level":3,"title":"第三步：配置全局设置","slug":"第三步-配置全局设置","link":"#第三步-配置全局设置","children":[]},{"level":3,"title":"第四步：查看数据与调整","slug":"第四步-查看数据与调整","link":"#第四步-查看数据与调整","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.5.6（2026）","slug":"v1-5-6-2026","link":"#v1-5-6-2026","children":[]}]}],"relativePath":"md/wordpress主题插件/WordPress 全能广告管理插件 — WZ Ad Manager.md","filePath":"md/wordpress主题插件/WordPress 全能广告管理插件 — WZ Ad Manager.md"}'),o={name:"md/wordpress主题插件/WordPress 全能广告管理插件 — WZ Ad Manager.md"};function n(i,e,s,d,h,b){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="wordpress-全能广告管理插件-—-wz-ad-manager" tabindex="-1">WordPress 全能广告管理插件 — WZ Ad Manager <a class="header-anchor" href="#wordpress-全能广告管理插件-—-wz-ad-manager" aria-label="Permalink to &quot;WordPress 全能广告管理插件 — WZ Ad Manager&quot;">​</a></h1><blockquote><p>支持图片和 HTML 代码两种广告类型，覆盖文章正文、列表信息流、弹窗、插屏、右下角、滑入、对联、顶部通栏、底部通栏、搜索页、归档页、404 页面等 20 余种投放位置，助您灵活变现网站流量。</p></blockquote><p><strong>版本</strong>：v1.5.6<br><strong>适配</strong>：WordPress 5.0+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-35.png" alt=""></p><p>本插件为 WordPress 网站提供一站式的广告投放管理方案，支持图片广告和 HTML 代码广告两种类型。您可以为每条广告自由选择 20 余个投放位置、指定生效时间范围、限定展示的文章分类，并通过权重或随机模式控制多广告轮播策略。</p><p>插件内置完善的广告展示控制逻辑：支持按权重轮播的 Cookie 机制、移动端独立开关、搜索引擎蜘蛛免展示，以及图片自适应缩放、新窗口打开、nofollow 等 SEO 友好选项。同时提供每日展现量和点击量的实时统计，方便您评估广告效果和调整投放策略。</p><p>后台管理界面采用三标签页布局（广告列表、添加广告、插件设置），支持列表内快速编辑图片地址、跳转链接、权重和时间范围，无需进入编辑页面即可完成日常调整。内置图库功能，可将广告素材上传至插件自有目录统一管理。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="_20-余种广告投放位置" tabindex="-1">20 余种广告投放位置 <a class="header-anchor" href="#_20-余种广告投放位置" aria-label="Permalink to &quot;20 余种广告投放位置&quot;">​</a></h3><p>插件将投放位置按场景分为四组，每条广告可同时勾选多个位置：</p><table tabindex="0"><thead><tr><th>分组</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>文章内</td><td>文章顶部、文章中部、文章底部、第 N 段后、H 标签后</td><td>嵌入文章正文内容区域，可指定段落序号或标题级别</td></tr><tr><td>文章周边</td><td>面包屑导航下方、评论区、原生推荐</td><td>围绕文章内容区域的辅助展示位</td></tr><tr><td>页面级</td><td>弹窗、插屏、右下角、滑入、对联、顶部通栏、底部通栏</td><td>独立于文章内容的全局展示位，支持倒计时、滚动触发等特殊交互</td></tr><tr><td>页面级</td><td>弹窗、插屏、右下角、滑入、对联、顶部通栏、底部通栏</td><td>独立于文章内容的全局展示位，支持倒计时、滚动触发等特殊交互</td></tr></tbody></table><p>每个位置均可在插件设置的「位置总开关」中独立启用或关闭。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-36.png" alt=""></p><h3 id="两种广告类型" tabindex="-1">两种广告类型 <a class="header-anchor" href="#两种广告类型" aria-label="Permalink to &quot;两种广告类型&quot;">​</a></h3><p>— <strong>图片广告</strong>：上传或粘贴图片 URL，支持设置跳转链接。图片自适应容器宽度，支持 object-fit 缩放模式（contain / cover / fill / none / scale-down），可限定最大宽度和固定宽高，支持自定义 alt 文本<br> — <strong>代码广告</strong>：粘贴任意 HTML 代码（如 Google AdSense、联盟广告等），插件自动过滤 script 标签、on 事件属性和 javascript: 伪协议，保障网站安全</p><h3 id="多广告轮播策略" tabindex="-1">多广告轮播策略 <a class="header-anchor" href="#多广告轮播策略" aria-label="Permalink to &quot;多广告轮播策略&quot;">​</a></h3><p>当同一位置存在多条符合条件的广告时，支持三种轮播模式：</p><p>— <strong>随机模式</strong>：每次页面加载随机展示一条，最简单公平<br> — <strong>权重轮播模式</strong>：按广告权重值从高到低排序，通过 Cookie 记录轮播位置，每次展示下一个广告，一小时后重置，实现按比例曝光<br> — <strong>全部展示模式</strong>：将该位置所有符合条件的广告同时输出</p><h3 id="广告定时投放" tabindex="-1">广告定时投放 <a class="header-anchor" href="#广告定时投放" aria-label="Permalink to &quot;广告定时投放&quot;">​</a></h3><p>每条广告可独立设置生效的起止时间。到达开始时间后自动上线展示，超过结束时间后自动停用，无需手动操作。适用于限时促销、节假日活动等场景。</p><h3 id="分类定向投放" tabindex="-1">分类定向投放 <a class="header-anchor" href="#分类定向投放" aria-label="Permalink to &quot;分类定向投放&quot;">​</a></h3><p>可指定广告仅在特定文章分类下展示。未设置分类限制的广告在所有文章中生效，实现精准的广告投放策略。</p><h3 id="每日数据统计" tabindex="-1">每日数据统计 <a class="header-anchor" href="#每日数据统计" aria-label="Permalink to &quot;每日数据统计&quot;">​</a></h3><p>插件通过 AJAX 自动收集每条广告的每日展现量和点击量，在广告列表中实时显示今日数据，方便您快速评估各广告位的效果表现。</p><h3 id="搜索引擎蜘蛛过滤" tabindex="-1">搜索引擎蜘蛛过滤 <a class="header-anchor" href="#搜索引擎蜘蛛过滤" aria-label="Permalink to &quot;搜索引擎蜘蛛过滤&quot;">​</a></h3><p>开启蜘蛛过滤后，插件会识别 Googlebot、Bingbot、Baiduspider、Sogou、360Spider 等主流搜索引擎爬虫的 User-Agent，对其隐藏所有广告内容，避免广告影响 SEO 收录和页面评分。</p><h3 id="移动端独立控制" tabindex="-1">移动端独立控制 <a class="header-anchor" href="#移动端独立控制" aria-label="Permalink to &quot;移动端独立控制&quot;">​</a></h3><p>插件内置移动设备检测，可一键关闭所有广告在手机、平板等设备上的展示，避免移动端广告影响用户体验。检测覆盖 Android、iPhone、iPad、Windows Phone 等主流移动平台。</p><h3 id="特殊广告交互" tabindex="-1">特殊广告交互 <a class="header-anchor" href="#特殊广告交互" aria-label="Permalink to &quot;特殊广告交互&quot;">​</a></h3><p>— <strong>弹窗广告</strong>：页面加载后弹出居中模态窗口，用户可点击关闭按钮或遮罩层关闭<br> — <strong>插屏广告</strong>：全屏覆盖式广告，带倒计时器和跳过按钮，倒计时结束后关闭按钮才可点击。关闭倒计时秒数可自定义（1-30 秒）<br> — <strong>滑入广告</strong>：用户滚动页面至设定百分比时从页面边缘滑入展示，可自定义触发比例（1-100%）和对齐方式。关闭后本次会话不再出现<br> — <strong>右下角广告</strong>：固定在页面右下角，可自定义距右侧边缘的像素距离<br> — <strong>对联广告</strong>：页面左右两侧各展示一条对联式广告，随页面滚动悬浮</p><h3 id="评论区广告精准插入" tabindex="-1">评论区广告精准插入 <a class="header-anchor" href="#评论区广告精准插入" aria-label="Permalink to &quot;评论区广告精准插入&quot;">​</a></h3><p>支持在文章评论区顶部、中间或底部插入广告，可设定广告展示次数（如仅在第一条评论后展示）。广告自动跟随评论区的 DOM 结构动态定位。</p><h3 id="列表信息流广告" tabindex="-1">列表信息流广告 <a class="header-anchor" href="#列表信息流广告" aria-label="Permalink to &quot;列表信息流广告&quot;">​</a></h3><p>在文章列表页（首页、分类页、标签页等）中，每隔指定条数插入一条信息流广告，原生融入列表布局。插入间隔数量可在每条广告中独立配置。</p><h3 id="内置图库管理" tabindex="-1">内置图库管理 <a class="header-anchor" href="#内置图库管理" aria-label="Permalink to &quot;内置图库管理&quot;">​</a></h3><p>插件提供独立的图片图库功能，支持上传 JPG、PNG、GIF、WebP 格式图片到插件自有目录。图库中的图片可在添加广告时一键选用，无需通过 WordPress 媒体库。</p><h3 id="列表内快速编辑" tabindex="-1">列表内快速编辑 <a class="header-anchor" href="#列表内快速编辑" aria-label="Permalink to &quot;列表内快速编辑&quot;">​</a></h3><p>广告列表中可直接修改图片 URL、跳转链接、权重值、生效时间范围，修改后即时保存，无需跳转到编辑页面，大幅提升日常管理效率。</p><h3 id="中英双语界面" tabindex="-1">中英双语界面 <a class="header-anchor" href="#中英双语界面" aria-label="Permalink to &quot;中英双语界面&quot;">​</a></h3><p>后台管理界面和前台广告标识均支持中文和英文两种语言，一键切换。所有文案通过统一的文本映射表管理，扩展和维护方便。</p><h3 id="广告标识与关闭" tabindex="-1">广告标识与关闭 <a class="header-anchor" href="#广告标识与关闭" aria-label="Permalink to &quot;广告标识与关闭&quot;">​</a></h3><p>前台展示的每条广告均附带「广告」标识徽章，明确告知用户内容性质。弹窗、插屏、滑入等特殊广告自带独立关闭按钮，其余位置的广告也提供统一的关闭功能，用户可手动关闭不感兴趣的广告内容。</p><h3 id="安全代码过滤" tabindex="-1">安全代码过滤 <a class="header-anchor" href="#安全代码过滤" aria-label="Permalink to &quot;安全代码过滤&quot;">​</a></h3><p>HTML 代码广告在输出前经过三层安全过滤：移除 script 标签及其内容、移除 on 事件属性、将 javascript: 伪协议链接替换为占位符。从源头杜绝 XSS 攻击风险。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 wz_ad 文件夹上传至网站 wp-content/plugins/ 目录，进入 WordPress 后台「插件」页面，找到「WZ Ad Manager 全能广告管理」并点击启用。启用后插件会自动创建所需的数据表，并在左侧菜单栏添加「广告管理」入口。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-37.png" alt=""></p><h3 id="第二步-创建广告" tabindex="-1">第二步：创建广告 <a class="header-anchor" href="#第二步-创建广告" aria-label="Permalink to &quot;第二步：创建广告&quot;">​</a></h3><p>进入后台「广告管理 → 添加广告」页面：</p><p>— 填写广告名称（必填），选择广告类型（图片广告或代码广告）<br> — 图片广告：上传图片或输入图片 URL，可选填点击跳转链接<br> — 代码广告：粘贴 HTML 广告代码，插件自动过滤危险标签<br> — 在「投放设置」区域勾选一个或多个展示位置。位置按分组排列，支持多选<br> — 可选设置：文章分类限制、权重值、生效起止时间、对齐方式<br> — 部分位置有专属设置项（如评论区位置/数量、段落序号、插屏倒计时秒数、信息流插入间隔、滑入触发比例、右下角边距等），勾选对应位置后自动展开</p><p>填写完毕后点击「保存广告」提交。</p><h3 id="第三步-配置全局设置" tabindex="-1">第三步：配置全局设置 <a class="header-anchor" href="#第三步-配置全局设置" aria-label="Permalink to &quot;第三步：配置全局设置&quot;">​</a></h3><p>进入后台「广告管理 → 插件设置」页面：</p><p>— 总开关：一键启用或停用所有广告展示<br> — 展示模式：选择随机、权重轮播或全部展示<br> — 移动端展示：开启或关闭移动设备上的广告<br> — 蜘蛛过滤：开启后对搜索引擎爬虫隐藏广告<br> — 图片设置：最大宽度、宽高限定、缩放模式、alt 文本<br> — 链接设置：新窗口打开、添加 nofollow 属性<br> — 位置总开关：独立控制 20 余个投放位置的启停<br> — 语言切换：中文 / 英文界面一键切换</p><h3 id="第四步-查看数据与调整" tabindex="-1">第四步：查看数据与调整 <a class="header-anchor" href="#第四步-查看数据与调整" aria-label="Permalink to &quot;第四步：查看数据与调整&quot;">​</a></h3><p>— 在「广告列表」页面查看所有广告及其今日展现量、点击量<br> — 直接在列表中修改图片 URL、跳转链接、权重、生效时间<br> — 点击「编辑」进入详细编辑页面，点击「启用/禁用」快速切换广告状态<br> — 通过「快速改位置」按钮可在弹窗中调整广告的投放位置</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件通过 WordPress 的 the_content 过滤器在文章内容中插入广告，与大多数主题兼容。如遇到广告位置异常，请检查主题是否使用了自定义的内容输出方式<br> — 代码广告仅支持安全的 HTML 内容，script 标签、事件属性和 javascript: 伪协议会被自动过滤移除。如需投放 JavaScript 广告代码（如 AdSense），建议通过 WordPress 小工具或主题自定义区域投放<br> — 插屏广告和弹窗广告在移动端可能影响用户体验和搜索引擎评分，建议配合「移动端展示」开关和「蜘蛛过滤」功能合理使用<br> — 权重轮播依赖 Cookie 机制，如用户浏览器禁用了 Cookie，将降级为按权重排序后展示第一条<br> — 分类定向仅在文章详情页生效，列表页、搜索页、404 页等非文章页面不受分类限制<br> — 每日统计数据的收集依赖前端 JavaScript，如用户浏览器禁用了 JS 或使用了广告拦截插件，统计数据可能不完整</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-5-6-2026" tabindex="-1">v1.5.6（2026） <a class="header-anchor" href="#v1-5-6-2026" aria-label="Permalink to &quot;v1.5.6（2026）&quot;">​</a></h3><p>— 新增插屏广告（Interstitial）功能，支持全屏覆盖展示、倒计时关闭和跳过按钮，关闭倒计时秒数可自定义<br> — 新增滑入广告（Scroll-in）功能，根据页面滚动百分比触发滑入展示，支持自定义触发比例和对齐方式<br> — 新增右下角广告（Corner）边距自定义，每条广告可独立设置距右侧边缘像素距离<br> — 新增评论区广告位置和展示次数控制，支持顶部、中间、底部三种插入位置<br> — 新增第 N 段后广告插入，可指定在文章第几个段落后展示广告<br> — 新增 H 标签后广告插入，可指定在文章第几个指定级别的标题后展示广告<br> — 新增列表信息流广告插入数量控制，可指定每隔几条文章插入一条广告<br> — 新增面包屑导航下方广告位和原生推荐广告位<br> — 新增中英双语界面支持，后台和前台文本一键切换<br> — 新增蜘蛛过滤功能，自动识别主流搜索引擎爬虫并隐藏广告<br> — 新增广告标识徽章和全局关闭按钮，明确告知用户广告内容<br> — 新增每日展现量、点击量 AJAX 统计<br> — 新增图片 object-fit 缩放模式控制和自定义宽高设置<br> — 新增广告链接 nofollow 属性选项<br> — 新增内置图库功能，支持上传管理 JPG、PNG、GIF、WebP 格式图片<br> — 优化后台管理界面，三标签页布局（广告列表 / 添加广告 / 插件设置），列表内支持快速编辑<br> — 优化安全代码过滤，三层过滤 script 标签、事件属性和 javascript: 伪协议<br> — 优化多广告轮播，支持随机、权重 Cookie 轮播和全部展示三种模式</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3065.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3065.html</a></p>',67)])])}const g=a(o,[["render",n]]);export{p as __pageData,g as default};
